Section Segs.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Definition expf_post (fr : bvmap 5 word) (regs : bvmap 5 word) (m : word -> option byte) (s : Z) (ret : word) (fin : machine_state) : Prop :=
  exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' ret M' rom /\ frm_zero cs' /\
    (forall r : reg, In (u r) fs_list -> reg_get fr' r = reg_get fr r) /\
    regs_agree (fun r => In r [2; 10; 11; 12]%list) regs regs' /\ getr regs' 2 = Z_to_bv 64 s /\ rinv [((s - 16)%Z, 16%Z)] m M'.

(* [comment removed for export] *)
Lemma expf_main : forall fr0 fr cs regs regs0 m (s : Z) (ret : word),
  frm_zero cs -> ret_ok ret -> getr regs 1 = ret -> getr regs 2 = Z_to_bv 64 s ->
  regs_agree (fun r => In r [2; 10; 11; 12]%list) regs0 regs -> (forall r : reg, In (u r) fs_list -> reg_get fr r = reg_get fr0 r) ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x3dbf0 : word) m rom) (expf_post fr0 regs0 m s ret).
Proof.
