Lemma expf_tail : forall fr0 fr cs regs regs0 m (s : Z) (ret : word),
  frm_zero cs -> ret_ok ret -> getr regs 1 = ret -> getr regs 2 = Z_to_bv 64 s -> getr regs 10 = Z_to_bv 64 0 ->
